"""Authored progression: worked examples, fading, retrieval, then transfer.

Expected results come from independent Python references, never the witness.
The world corpus is an optional advanced shelf, not a beginner curriculum.
"""
from __future__ import annotations


def lesson(id, chapter, title, concept, story, goal, starter, solution, inputs,
           reference, hints, discovery, *, review=(), prediction=None, macros=False):
    examples = [{"input": x, "output": reference(x)} for x in inputs]
    return dict(id=id, chapter=chapter, title=title, concept=concept, story=story,
                goal=goal, starter=starter, solution=solution, examples=examples[:3],
                heldout=examples[3:], hints=hints, discovery=discovery,
                review=list(review), prediction=prediction, macros=macros,
                source="Signal House · authored curriculum")


